import os
# Check ext directory structure
ext_path = "ext"
if os.path.exists(ext_path):
    for root, dirs, files in os.walk(ext_path):
        level = root.replace(ext_path, '').count(os.sep)
        indent = ' ' * 2 * level
        print(f'{indent}{os.path.basename(root)}/')
        subindent = ' ' * 2 * (level + 1)
        for file in files:
            print(f'{subindent}{file}')
else:
    print("ext/ does not exist")

# Also check if there's an existing system_prompt file
for p in ["ext/skills", "ext/tools", "ext/commands"]:
    if os.path.exists(p):
        print(f"\n{p} exists")
    else:
        print(f"\n{p} does not exist")
