import os

ext_path = "ext"
exists = os.path.exists(ext_path)
print(f"ext exists: {exists}")

if exists:
    items = os.listdir(ext_path)
    print(f"ext contents: {items}")
    for item in items:
        full = os.path.join(ext_path, item)
        if os.path.isdir(full):
            print(f"  dir: {item} -> {os.listdir(full)}")
        else:
            print(f"  file: {item} ({os.path.getsize(full)} bytes)")
